    "Script": "CommonCacheScripts = {
    init: async function (app, container) {
        app = app || session.app;
        container = container || $(".component[name=CommonCacheScripts]");
        var scriptData = await CommonCacheScripts.getDataSource("ContentManagement/CommonObject/Latest()?type=ContentManagement/Script&$orderby=Name asc");
