.docs-nav-grid[data-columns="2"]{grid-template-columns:repeat(2,minmax(0,1fr))}
.docs-nav-grid[data-columns="3"]{grid-template-columns:repeat(3,minmax(0,1fr))}
.docs-nav-card{display:flex;flex-direction:column;gap:var(--site-gap);padding:calc(var(--site-gap) * 1.5);border:var(--site-border);box-shadow:var(--site-shadow);background:var(--site-surface)}
