h1::before,h1::after,h2::before,h2::after,h3::before,h3::after,h4::before,h4::after,h5::before,h5::after,h6::before,h6::after,.docs-nav-title::before,.docs-nav-title::after{align-self:center;vertical-align:middle;line-height:1;transform:none}

